import { readFile, writeFile } from 'node:fs/promises';

const sourcePath = new URL('../hq.html', import.meta.url);
const targetPath = new URL('../hq-protected.php', import.meta.url);
const source = await readFile(sourcePath, 'utf8');

const guard = `<?php
// Generated by scripts/build-protected-hq.mjs. Do not edit this file.
if ( ! defined( 'ABSPATH' ) ) {
    http_response_code( 404 );
    header( 'Cache-Control: no-store, private' );
    exit;
}
?>
`;

const output = guard + source;

if ((globalThis.process?.argv || []).includes('--check')) {
  const existing = await readFile(targetPath, 'utf8').catch(() => '');
  if (existing !== output) {
    console.error('hq-protected.php fehlt oder ist nicht mit hq.html synchron.');
    globalThis.process.exitCode = 1;
  } else {
    console.log('✓ hq-protected.php ist geschützt und synchron');
  }
} else {
  await writeFile(targetPath, output, 'utf8');
  console.log('✓ hq-protected.php erzeugt');
}
